// ---------------------------------------------------------------------------
// Container — the default export
// ---------------------------------------------------------------------------

/**
 * The component SFCC actually renders. Base `_app/index.jsx` resolves
 * `@salesforce/retail-react-app/app/components/footer` through the overrides system
 * and renders `<Footer />` with **no props**, so there is no upstream container to
 * own the data. This wrapper is that seam, and the only place static content lives.
 *
 * HPC-034: replace FOOTER_FIXTURE with the Contentful CDA fetch **here** — the
 * presentational Footer above does not change. Note that puts a fetch inside
 * `components/`, which components.md reserves for containers; if that matters,
 * HPC-034 should override `_app` instead (Tier 2 shared shell — coordinate first).
 */
const FooterContainer = (props: Omit<FooterProps, 'data'>) => {
  // buildUrl + history.push, not useNavigation. useNavigation special-cases the home path
  // (`path === '/' ? '/' : updatedHref`), so navigate('/') pushes a bare '/' and skips the
  // site/locale prefix — on a prefixed storefront that drops the shopper onto the default
  // site. This is the exact pair base _app's onLogoClick uses, so both wordmarks resolve
  // home the same way on every storefront.
  const { buildUrl } = useMultiSite();
  const history = useHistory();
  return <Footer data={FOOTER_FIXTURE} onLogoClick={() => history.push(buildUrl(HOME_HREF))} {...props} />;
};

export default FooterContainer;

